import 'form_detection/form_score.dart';

export 'form_detection/form_score.dart';

/// Complete evaluation report generated by the AI Exercise Form Coach.
class ExerciseFormReport {
  final String id;
  final String userId;
  final String exerciseName;
  final String videoPath;
  final double videoDurationSeconds;
  final FormScore score;
  final List<FormIssue> detectedIssues;
  final List<String> positiveFeedback;
  final List<String> recommendations;
  final String coachSummary;
  final Map<String, dynamic> landmarkData;
  final DateTime createdAt;

  const ExerciseFormReport({
    required this.id,
    required this.userId,
    required this.exerciseName,
    required this.videoPath,
    this.videoDurationSeconds = 0.0,
    required this.score,
    this.detectedIssues = const [],
    this.positiveFeedback = const [],
    this.recommendations = const [],
    this.coachSummary = '',
    this.landmarkData = const {},
    required this.createdAt,
  });

  factory ExerciseFormReport.fromJson(Map<String, dynamic> json) {
    return ExerciseFormReport(
      id: json['id']?.toString() ?? 'report_${DateTime.now().millisecondsSinceEpoch}',
      userId: json['userId']?.toString() ?? json['user_id']?.toString() ?? 'usr_anonymous',
      exerciseName: json['exerciseName']?.toString() ?? json['exercise_name']?.toString() ?? 'Squat',
      videoPath: json['videoPath']?.toString() ?? json['video_path']?.toString() ?? '',
      videoDurationSeconds: (json['videoDurationSeconds'] as num?)?.toDouble() ??
          (json['video_duration_seconds'] as num?)?.toDouble() ??
          0.0,
      score: json['score'] is Map<String, dynamic>
          ? FormScore.fromJson(Map<String, dynamic>.from(json['score'] as Map))
          : FormScore.fromJson({
              'overallScore': (json['score'] as num?)?.toDouble() ?? 80.0,
            }),
      detectedIssues: (json['detectedIssues'] as List?)
              ?.map((item) => FormIssue.fromJson(Map<String, dynamic>.from(item as Map)))
              .toList() ??
          (json['issues'] as List?)
              ?.map((item) => FormIssue.fromJson(Map<String, dynamic>.from(item as Map)))
              .toList() ??
          const [],
      positiveFeedback: (json['positiveFeedback'] as List?)
              ?.map((e) => e.toString())
              .toList() ??
          (json['positive_feedback'] as List?)
              ?.map((e) => e.toString())
              .toList() ??
          const [],
      recommendations: (json['recommendations'] as List?)
              ?.map((e) => e.toString())
              .toList() ??
          const [],
      coachSummary: json['coachSummary']?.toString() ??
          json['coach_summary']?.toString() ??
          '',
      landmarkData: json['landmarkData'] is Map
          ? Map<String, dynamic>.from(json['landmarkData'] as Map)
          : (json['landmark_data'] is Map
              ? Map<String, dynamic>.from(json['landmark_data'] as Map)
              : const {}),
      createdAt: json['createdAt'] != null
          ? DateTime.parse(json['createdAt'].toString())
          : (json['created_at'] != null
              ? DateTime.parse(json['created_at'].toString())
              : DateTime.now()),
    );
  }

  Map<String, dynamic> toJson() => {
    'id': id,
    'userId': userId,
    'exerciseName': exerciseName,
    'videoPath': videoPath,
    'videoDurationSeconds': videoDurationSeconds,
    'score': score.toJson(),
    'detectedIssues': detectedIssues.map((e) => e.toJson()).toList(),
    'positiveFeedback': positiveFeedback,
    'recommendations': recommendations,
    'coachSummary': coachSummary,
    'landmarkData': landmarkData,
    'createdAt': createdAt.toIso8601String(),
  };
}
